WITH valid AS (SELECT id, store_name, city, region, sqft, ROUND(sqft, 2) sqft_rounded, COALESCE(region, 'UNKNOWN') region_clean FROM stores WHERE store_name LIKE '%Rive%'), latest_match AS (SELECT s.id, s.store_name, s.city, s.region, s.sqft_rounded, s.region_clean, top1.units, top1.store_sale_revenue FROM valid s JOIN LATERAL (SELECT c.units, c.revenue AS store_sale_revenue FROM store_sales c WHERE c.store_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) top1 ON TRUE), with_last AS (SELECT s.id, s.store_name, s.region, s.sqft_rounded, s.region_clean, s.store_sale_revenue, x.store_sale_sale_date, x.store_sale_units FROM latest_match s LEFT JOIN LATERAL (SELECT c.sale_date AS store_sale_sale_date, c.units AS store_sale_units FROM store_sales c WHERE c.store_id = s.id ORDER BY c.revenue DESC, c.id DESC LIMIT 1) x ON TRUE), latest_match_stores AS (SELECT s.*, top1.units FROM with_last s LEFT JOIN LATERAL (SELECT c.units FROM store_sales c WHERE c.store_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) top1 ON TRUE), deduped AS (SELECT id, store_name, store_sale_revenue, store_sale_units, units FROM latest_match_stores QUALIFY ROW_NUMBER() OVER (PARTITION BY region ORDER BY store_sale_units NULLS LAST, id) = 1) SELECT id, store_name, store_sale_revenue, store_sale_units, CASE WHEN store_name RLIKE '^(Old Town|Downtown Express)$' THEN 'GROUP_A' WHEN store_name RLIKE '^(Siam Flagship|Airport Kiosk)$' THEN 'CORE' ELSE 'PRIORITY' END AS store_name_zone FROM deduped ORDER BY id NULLS LAST;
